def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 70
    WATER_REQ = 13

    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    total_players = 1 + len(alive_opponents)
    safe_slots = int(supply // WATER_REQ)
    contested = safe_slots < total_players

    prev_bids = []
    desperate_opponents = 0
    rich_opponents = 0
    for opp in alive_opponents:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_opponents += 1
        if opp.get('budget', 0) > budget:
            rich_opponents += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)

    highest_prev = max(prev_bids) if prev_bids else 0

    if hp <= 2 or no_water_days >= 2:
        target = DAILY_SALARY * 0.96
        if contested and highest_prev > 0:
            target = max(target, highest_prev + 2)
        return min(budget, target)

    if hp <= 4 or no_water_days >= 1:
        if contested:
            target = max(DAILY_SALARY * 0.72, highest_prev + 1.5 if highest_prev > 0 else DAILY_SALARY * 0.72)
        else:
            target = DAILY_SALARY * 0.48
        return min(budget, target)

    if not contested:
        if supply >= 24:
            target = DAILY_SALARY * 0.18
        elif supply >= 20:
            target = DAILY_SALARY * 0.28
        else:
            target = DAILY_SALARY * 0.36
        return min(budget, target)

    pressure = 0
    if highest_prev >= DAILY_SALARY * 0.85:
        pressure += 2
    elif highest_prev >= DAILY_SALARY * 0.6:
        pressure += 1
    if desperate_opponents > 0:
        pressure += 1
    if rich_opponents > len(alive_opponents) / 2.0:
        pressure += 1

    if pressure >= 3:
        target = DAILY_SALARY * 0.83
    elif pressure == 2:
        target = DAILY_SALARY * 0.68
    elif pressure == 1:
        target = DAILY_SALARY * 0.58
    else:
        target = DAILY_SALARY * 0.46

    if highest_prev > 0 and pressure >= 1:
        target = max(target, highest_prev + 1.0)

    if budget < DAILY_SALARY * 2:
        target = min(target, DAILY_SALARY * 0.55)

    return min(budget, target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Scenario 1: No active opponents or I'm the only one left.
    if not alive_opponents:
        # Bid just enough to get water, or a small amount to save budget.
        # Ensure the bid is at least WATER_REQ * 1 (cost of water) to secure water.
        return min(my_status['budget'], max(WATER_REQ * 1.5, DAILY_SALARY * 0.1))

    # Collect yesterday's bids from active opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Calculate total water needed by all alive players (including me)
    total_water_needed_by_alive = WATER_REQ
    for opp in alive_opponents:
        total_water_needed_by_alive += opp['water_requirement']

    # Scenario 2: Emergency - My HP is very low
    if my_status['hp'] <= 2:
        # Bid very high to ensure water, almost max salary
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # Scenario 3: Analyze previous bids and supply
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        # Check if supply is tight (less than 1.2x total demand)
        is_supply_tight = day_context['supply'] < total_water_needed_by_alive * 1.2
        # Check if opponents were very aggressive yesterday (bid high)
        were_opponents_aggressive = highest_prev_bid >= DAILY_SALARY * 0.75

        if is_supply_tight or were_opponents_aggressive:
            # High competition or scarcity, bid aggressively
            if my_status['hp'] <= 3: # Still somewhat low HP, be very aggressive
                return min(my_status['budget'], DAILY_SALARY * 0.9)
            else: # Moderate HP, but competition is high
                # Bid above the highest previous bid, but not max salary
                return min(my_status['budget'], max(DAILY_SALARY * 0.6, highest_prev_bid + 5))
        else:
            # Supply is not tight and opponents were not overly aggressive
            # Try to save money, but stay competitive
            if my_status['hp'] > 5: # High HP, can afford to save more
                # Bid lower than average previous bid, but ensure it's enough to get water
                return min(my_status['budget'], max(WATER_REQ * 1.5, DAILY_SALARY * 0.3, avg_prev_bid - 5))
            else: # Moderate HP, be a bit more cautious
                # Bid slightly above average previous bid
                return min(my_status['budget'], max(DAILY_SALARY * 0.4, avg_prev_bid + 1))

    # Scenario 4: No yesterday's bids (e.g., Day 1 or all opponents are new/no trace)
    else:
        # General strategy without previous bid data
        # Check if supply is abundant (more than 1.5x total demand)
        is_supply_abundant = day_context['supply'] > total_water_needed_by_alive * 1.5

        if is_supply_abundant:
            # Bid low to save money
            return min(my_status['budget'], max(WATER_REQ * 1.5, DAILY_SALARY * 0.3))
        else:
            # Supply is not abundant, moderate competition expected
            # Bid moderately to secure water
            return min(my_status['budget'], DAILY_SALARY * 0.55)

